<form method="get" class="filter-bar">
    <?php if (!empty($search)): ?><label class="field search-field"><span><?= e(t('Search')) ?></span><input type="search" name="q" value="<?= e($filters['q'] ?? '') ?>" placeholder="<?= e(t('Notes or person’s name')) ?>"></label><?php endif ?>
    <label class="field"><span><?= e(t('Business / personal')) ?></span><select name="business_id"><option value=""><?= e(t('All businesses & personal')) ?></option><?php foreach ($businesses as $business): ?><option value="<?= $business['id'] ?>"<?= selected($filters['business_id'] ?? '',$business['id']) ?>><?= e($business['name']) ?></option><?php endforeach ?></select></label>
    <?php if (empty($simple)): ?><label class="field"><span><?= e(t('Account book')) ?></span><select name="book_id"><option value=""><?= e(t('All account books')) ?></option><?php foreach ($books as $book): ?><option value="<?= $book['id'] ?>"<?= selected($filters['book_id'] ?? '',$book['id']) ?>><?= e($book['name']) ?></option><?php endforeach ?></select></label><label class="field"><span><?= e(t('Category')) ?></span><select name="category_id"><option value=""><?= e(t('All categories')) ?></option><?php foreach ($categories as $category): ?><option value="<?= $category['id'] ?>"<?= selected($filters['category_id'] ?? '',$category['id']) ?>><?= e($category['name']) ?></option><?php endforeach ?></select></label><label class="field"><span><?= e(t('Type')) ?></span><select name="kind"><option value=""><?= e(t('All types')) ?></option><?php foreach (['income','expense','transfer'] as $kind): ?><option value="<?= $kind ?>"<?= selected($filters['kind'] ?? '',$kind) ?>><?= e(t(ucfirst($kind))) ?></option><?php endforeach ?></select></label><?php endif ?>
    <label class="field date-field"><span><?= e(t('From')) ?></span><input type="date" name="from" value="<?= e($filters['from']) ?>" required min="1900-01-01" max="9999-12-31"></label><label class="field date-field"><span><?= e(t('To')) ?></span><input type="date" name="to" value="<?= e($filters['to']) ?>" required min="1900-01-01" max="9999-12-31"></label>
    <div class="filter-actions"><button class="button" type="submit"><?= e(t('Apply filters')) ?></button><a class="text-button" href="<?= url(strtok(current_route(),'?') ?: '') ?>"><?= e(t('Reset')) ?></a></div>
</form>
